iir_b_coeffs = [1+alpha, -2*np.cos(2*np.pi*freq/samp_freq)*(1+alpha), 1+alpha]
iir_a_coeffs = [1+alpha, -2*(alpha+rho)*np.cos(2*np.pi*freq/samp_freq), (rho*rho+alpha)]

# --- Conversions ---
# 1. FIR Q15 Quantization
fir_q15 = np.clip(np.round(fir_coeffs * 32768.0), -32768, 32767).astype(int)

# 2. IIR SOS Decomposition (Shape: [N_STAGES, 6] -> [b0, b1, b2, a0, a1, a2])
sos = signal.tf2sos(iir_b_coeffs, iir_a_coeffs)
iir_stages = len(sos)

# 3. Extract [b0, b1, b2, a1, a2] (dropping a0=1.0) for ESP-DSP dsps_biquad_f32
iir_f32_biquads = sos[:, [0, 1, 2, 4, 5]]

# 4. IIR Q14 Quantization: round(float * 16384.0)
iir_q14_raw = np.clip(np.round(iir_f32_biquads * 16384.0), -32768, 32767).astype(int)


# --- Formatter Helper ---
def format_array(arr, per_line=5, fmt="{:.9f}f"):
    lines = []
    for i in range(0, len(arr), per_line):
        chunk = arr[i:i + per_line]
        lines.append("    " + ", ".join(fmt.format(x) for x in chunk))
    return ",\n".join(lines)


